  Item_10022_Desc = {
    Text = "Bạn sẽ bất diệt. \nKý ức ngưng tụ rơi ra từ sự tồn tại siêu nghiệm, dùng để đổi vật phẩm trong cửa hàng Misaq."
  },
  Item_10022_Name = {
