  Item_10105_Desc = {
    Text = "Các thuộc tính chính sẽ ngẫu nhiên giữa Tỉ Lệ Chí Mạng, Sát Thương Chí Mạng, Hồi Ánh Bạc, Hồi Aliemus."
  },
  Item_10105_Name = {
    Text = "Kén Nhộng Của Thiếu Nữ Ⅰ"
  },
  Item_10105_StoryDesc = {
    Text = "Tôi tặng cậu kén nhộng của tôi, là thân xác thuần khiết nhất."
  },
  Item_10106_Desc = {
    Text = "Sự cung cấp dồi dào được phê duyệt đặc biệt bởi Phó viện trưởng Khổ Lệ Đặc.\nHộp gỗ bọc các vật liệu quý giá, cung cấp sự hỗ trợ cho những Người Giữ Gìn thực hiện nhiệm vụ thử thách hàng ngày và hàng tuần trong lớp học mật cảnh.\nChọn một trong các vật liệu sau:\nChương Bí Mật Trắng Sạch*12\nTemper tâm hồn*12\nBản sao ý thức*12\nMô hình linh tri thức*12"
  },
  Item_10106_Name = {
    Text = "Bổ sung cấp II (đã bị loại bỏ)"
  },
  Item_10107_Desc = {
    Text = "Bản chất của bí ẩn chính là kiến thức cấm kỵ và khó nhận biết. Sau khi sử dụng bản khắc để tái tạo, lực lượng của bí ẩn sẽ được tăng cường thêm."
  },
  Item_10107_Name = {
    Text = "Bí ẩn (đã bị loại bỏ)"
  },
  Item_10108_Desc = {
    Text = "Là tên gọi thanh lịch của tiền tệ được lưu hành trong Vương quốc. Nơi nào cũng có, nơi nào cũng cần."
  },
  Item_10108_Name = {
