  Item_123552_Desc = {
    Text = "\"Đường tuyết đẹp quá... Hả? Ai nói tôi muốn! Nhưng nếu không nhận thì bạn sẽ thất vọng chứ... Cảm ơn nhé.\""
  },
  Item_123552_Name = {
    Text = "Bữa tiệc bánh gừng·Kẻ khắc sét"
  },
  Item_123553_Desc = {
    Text = "\"Đêm bạc sương vui vẻ, Người Giữ Gìn. Đây, đây là quà tặng.\""
  },
  Item_123553_EmojiName = {
    Text = "Tặng bạn quà"
  },
  Item_123553_Name = {
    Text = "Bốt Lợi Khắc Tư·tặng bạn quà"
  },
  Item_123554_Desc = {
    Text = "\"Ôi trời ơi, đoán xem trong chiếc hộp mà pháp sư ném tới là quà tặng hay bom?\""
  },
  Item_123554_EmojiName = {Text = "Ném"},
  Item_123554_Name = {
    Text = "Kasia·Ném"
  },
  Item_123555_Desc = {
    Text = "\"Liệu ngài có thể dừng lại với tôi trong rừng một giờ không? Tôi muốn... cảm nhận lại hương vị của ngôi nhà kẹo một lần nữa.\""
  },
  Item_123555_Name = {
    Text = "Tiệc bánh gừng·Ôrla"
  },
  Item_123556_Desc = {
    Text = "\"Tôi sẽ cố gắng chiếu sáng đêm sương bạc của mọi người.\""
  },
  Item_123556_EmojiName = {
    Text = "Phát sáng"
  },
  Item_123556_Name = {
    Text = "Pháp Luân Tư: Phát Quang"
  },
  Item_123557_Desc = {
    Text = "\"Tối nay, chúng ta sẽ thưởng thức bánh gừng và siro phong để cùng chúc mừng bữa tiệc vĩ đại này!\""
  },
  Item_123557_Name = {
    Text = "Bánh gừng tiệc·Đỗ Lê Sa Yên"
  },
  Item_123558_Desc = {
    Text = "\"Chúc mừng Lễ Hội Đông Độ, ân nhân. À... mũ đè lên lông vũ rồi\""
  },
  Item_123558_EmojiName = {
    Text = "Chúc mừng Lễ Hội Đông Độ"
  },
  Item_123558_Name = {
    Text = "Chúc mừng Lễ Hội Đông Độ Cas-tơ-lơ"
  },
  Item_123559_Desc = {
    Text = "Một thực thể không rõ danh tính đã để lại bức thư mời này trong hộp thư của bạn—— cùng với một ít vụn bánh gừng thơm phức. \n Sau khi sử dụng, bạn có thể chọn một hình đại diện trong bộ \"Tiệc Bánh Gừng\" mà bạn chưa có."
  },
  Item_123559_Name = {
    Text = "Lời mời đến buổi tiệc bánh gừng"
  },
  Item_123560_Desc = {
    Text = "Truyền thuyết rằng vào đêm Đêm sương bạc, treo tất ở đầu giường, vào sáng sớm Lễ Hội Đông Truyệt sẽ nhận được quà tặng bí ẩn. Nhớ rằng, nhất định phải treo tất đã giặt sạch. \nSau khi sử dụng có thể chọn một biểu cảm chiến đấu \"Misaque Lễ Hội Đông Truyệt\" chưa từng nhận được."
  },
  Item_123560_Name = {
    Text = "Phiếu quà Lễ Hội Đông Độ"
  },
  Item_123561_Desc = {
    Text = "\"Làm gì, sao ngươi dám nhìn ta bằng biểu cảm bất kính như vậy?!\""
  },
  Item_123561_EmojiName = {Text = "Tất"},
  Item_123561_Name = {
    Text = "Điên Vọng · Muphí · tất"
  },
  Item_123638_Desc = {
    Text = "Những đứa trẻ đã chuẩn bị chiếc hộp ước nguyện trước đêm sương bạc, trên đó dán những mảnh giấy ghi món quà mà chúng mong muốn. \n \"Tôi đã làm một đứa trẻ ngoan cả năm rồi, giờ thì sứ giả mùa đông chắc phải tặng quà cho tôi chứ!\""
  },
  Item_123638_Name = {
    Text = "Hòm cầu nguyện sương bạc"
  },
  Item_123639_Desc = {
    Text = "Hộp quà đặc biệt chỉ xuất hiện vào sáng sớm Lễ Hội Đông Độ, sau khi được mở sẽ nhanh chóng biến mất, vì vậy rất ít người biết đến bí mật này. \n \"Suỵt, đây là bí mật giữa những đứa trẻ ngoan và sứ giả Đông Độ nhé.\""
  },
  Item_123639_Name = {
    Text = "Hộp quà Lễ Hội Đông Độ"
  },
  Item_123757_Desc = {
    Text = "Có thể nhận được sau khi mua \"Khóa Đề Cốt Lõi\" trong \"Khóa Đề Học Kỳ\".\n \"Cảm, cảm ơn ngài... A! Xin đừng lại gần... sẽ, sẽ làm ngài bị thương đấy...\""
  },
  Item_123757_Name = {
    Text = "Ngày hôm qua không bao giờ phai nhạt: Phiệt"
  },
  Item_123757_StoryDesc = {
    Text = "Khóa đề học kỳ kỳ 29"
  },
  Item_124899_Desc = {
    Text = "Sau khi ghi nhận Thược Lệnh này, có thể chọn kỹ năng Thược Lệnh:\"La Võng Luân Chuyển\" khi biên đội.\n\nDệt, đo lường, và cắt đứt.\nThần minh của vận mệnh không buồn không vui, bánh xe vận mệnh vĩnh viễn không ngừng."
  },
  Item_124899_Name = {
    Text = "La Võng Luân Chuyển"
  },
  Item_124899_StoryDesc = {
    Text = "Dệt, đo lường, và cắt đứt.\nThần minh của vận mệnh không buồn không vui, bánh xe vận mệnh vĩnh viễn không ngừng."
  },
  Item_125136_Desc = {
    Text = "Vòng mệnh với thuộc tính sát thương mạnh mẽ."
  },
  Item_125136_Name = {
    Text = "Mồi hoa ngọc lan"
  },
  Item_125136_StoryDesc = {
    Text = "Đó là năm thứ hai tôi và cha chuyển đến thành phố biển, những lời khóc lóc của Evelyn trong bức thư làm tôi bối rối, tôi đã quyết tâm chia tay cô ấy. Đây là một vùng đất giàu có được trang trí bằng lụa và gỗ mun, tất cả những kẻ ăn mày đều ngửi thấy sự hỗn loạn khi nó đang ngủ, giá trị của tiền giấy có thể đổi lấy vàng nặng bằng với nó, nắm giữ những tuyến đường đó, có thể khuấy động hàng triệu lần tài sản với chi phí rất nhỏ. \n Tuy nhiên, Evelyn, có lẽ do nguồn gốc huyền bí khó hiểu của cô ấy dẫn đến sự thần kinh, người phụ nữ này tin tưởng vào cái gọi là thông điệp từ tổ tiên, ở phương Đông có những thần linh kỳ quái mà các nhánh bên của họ thờ phụng, giống như một loại cá nào đó trong đại dương sâu thẳm, sẽ treo xuống những món mồi hấp dẫn, dẫn dụ con mồi vào một cuộc ăn chậm chạp khó nhận ra. \n Cô ấy đã sai, thành phố biển không có một chút vị mặn nào từ biển. \n Chỉ có những bông hoa ngọc lan chồng chất, nồng nàn đến mức mê hoặc, lại làm cho người ta sợ hãi. \n Những bông hoa ngọc lan đã khiến cả tôi và cha cùng sa vào. \n Khi tôi nhìn thấy cô ấy, bóng dáng của người phụ nữ tên là \"Xu\" xuất hiện trong tầm mắt tôi trong giây phút đầu tiên, tôi đã không còn khả năng thoát khỏi vùng đất cổ xưa này nữa. \n Cô ấy khiến người ta muốn lại gần, khiến người ta muốn chiếm hữu, khiến người ta muốn @3 \n Cô ấy khiến khiến khiến khiến khiến khiến người ta muốn muốn muốn muốn muốn \n\n Cắt nhỏ, chẻ ra, chặt đứt mãi mãi mãi mãi mãi mãi... @2@3@2!! \n A, tại sao tôi đến đây? Tôi muốn mang đi cái gì? Tôi là... ai? \n Không còn quan trọng nữa, cô ấy đã mời tôi, tôi ngồi trước bàn trong ngôi nhà lớn đó. \n Cha tôi, người đã điên rồ như tôi, mặt mày nở nụ cười ngoan ngoãn, những món ăn phong phú được bày biện trên bàn ăn, làm cho cái đĩa kim loại có nắp trở nên lạc lõng. \n\n Xu ngồi ngược ánh sáng trong ánh hoàng hôn, hào quang bao quanh cô ấy như một viền vàng mềm mại, từ từ, chiếc quạt đen đó đã được hạ xuống. \n Giống như Evelyn, như bạn chơi của tôi hồi nhỏ, như một cuộc tình lờ mờ... như mẹ tôi. \n Đó là một gương mặt xinh đẹp thẳng thắn như tượng thần được mạ vàng trong đền thờ. \n Tôi không nghe thấy tiếng hút, cũng không ngửi thấy mùi tanh từ cha, chỉ chăm chú nhìn gương mặt đó, và chủ nhân của gương mặt đó đưa ra một bàn tay trắng muốt, mở nắp đĩa, nhặt một miếng thịt phù hợp, cô ấy dùng hai que gỗ mỏng để gắp lên, nâng cao. \n Cô ấy gọi tôi, mỡ động vật đã được nướng rơi xuống khóe miệng tôi. \n \"Tiểu tiên sinh, bạn nên ăn một chút.\"\n Tôi ngoan ngoãn và ngớ ngẩn há miệng ra. \n Hoa ngọc lan đã nở, nó đang từ từ treo xuống hướng về phía tôi. \n — \"Nhật ký của người vô danh\""
  },
  Item_125137_Desc = {
    Text = "Đàn ông tranh nhau dâng lên những báu vật kỳ lạ, nhưng lại lần lượt bị yêu cầu mỗi ngày mua về nồi bánh đường lê đặc sánh ngọt ngào nhất.\nCô ấy sẽ không để nó làm bệnh rỉ sét răng của tiểu thư nhỏ, giống như tà thần luôn thích ứng lời những điều ước xấu xa.\n\nRơi ra ít nhất {s1} cái"
  },
  Item_125137_Name = {
    Text = "Bánh đường lê"
