  Item_125186_Name = {
    Text = "Bánh đường lê"
  },
  Item_125187_Desc = {
    Text = "Đó là linh thức của ý chí cổ xưa đã mất. Misaque thông qua nghi lễ bí ẩn để khơi dậy linh thức của thể thức tỉnh, thể thức tỉnh được khơi dậy sẽ tăng cường khả năng tâm linh vĩnh viễn. \n Lặp lại việc nhận được Tuần, dùng để kích hoạt khởi linh của Tuần."
  },
  Item_125187_Name = {
    Text = "Mảnh vỡ·Tuần"
  },
  Item_125187_StoryDesc = {
    Text = "Lặp lại việc chuyển đổi khi nhận được Tuần, dùng để kích hoạt khởi linh của Tuần."
  },
