  Item_125189_Desc = {
    Text = "Đàn ông tranh nhau dâng lên những báu vật kỳ lạ, nhưng lại lần lượt bị yêu cầu mỗi ngày mua về nồi bánh đường lê đặc sánh ngọt ngào nhất.\nCô ấy sẽ không để nó làm bệnh rỉ sét răng của tiểu thư nhỏ, giống như tà thần luôn thích ứng lời những điều ước xấu xa.\n\nRơi ra ít nhất {s1} cái"
  },
  Item_125189_Name = {
    Text = "Bánh đường lê"
  },
  Item_125190_Desc = {
    Text = "Ghi lại lệnh khóa này, bạn có thể chọn kỹ năng lệnh khóa:\"Ký ức về ngôi nhà sâu\".\n\nTrong căn nhà sâu kín chôn giấu quá nhiều bí mật, về quyền lực, về cuồng si, về dục vọng.\nVề việc thần ác nhìn xuống trần gian, chứa đựng tình yêu \"hạnh phúc\" và \"Sự biến dạng\"."
  },
  Item_125190_Name = {
    Text = "Ký ức về ngôi nhà sâu"
  },
