  Item_126361_Desc = {
    Text = "Sau khi mở khóa, hoàn thành toàn bộ nhiệm vụ\"Mệnh Lũ Kỷ Hành\" có thể nhận thêm phần thưởng sau"
  },
  Item_126361_Name = {
    Text = "Kỷ Hành Mệnh Lũ"
  },
  Item_126362_Desc = {
    Text = "Bộ Hậu cần đã cấp giấy phép đặc biệt cho những Người Giữ Gìn hoàn thành \"điều tra hành động\". Mỗi lần hoàn thành điều tra hành động, Người Giữ Gìn có thể mua một loạt các sản phẩm bạc tâm quý hiếm đặc biệt cho chuyến xuất phát tiếp theo. \n Số lượng có hạn, mong rằng chìa khóa bạc sẽ dẫn dắt chúng ta."
  },
  Item_126362_Name = {
    Text = "Bonus của hành trình điều tra · Bài sao V"
  },
  Item_126491_Desc = {
    Text = "Có thể nhận được trong \"Tạp Chí Cổ Quốc\". \n \"Không cần phải lo lắng về những điều vụn vặt nữa. \n Tất cả những suy nghĩ và đam mê sẽ mãi mãi gắn kết với hình dáng không thể nói ra dưới đó.\""
  },
  Item_126491_Name = {
