  Item_127525_StoryDesc = {
    Text = "Avatar sự kiện đăng nhập trên PC"
  },
  Item_128552_Name = {Text = "Vé xe"},
  Item_128659_Desc = {
    Text = "Không chỉ vào ngày lễ cầu năm, mà suốt nửa tháng tiếp theo, khắp nơi ở Quốc gia Bàn Long sẽ tràn ngập bầu không khí vui vẻ. \nMọi người mang theo quà tặng, đi thăm bạn bè và người thân. Tất cả những thứ tốt đẹp tượng trưng cho sự giàu có, niềm vui và ý nghĩa phúc lành, sẽ được nhét vào chiếc hộp quà với những lời chúc tốt đẹp nhất."
  },
  Item_128659_Name = {
    Text = "Hộp hồng vận cầu năm"
  },
  Item_128660_Desc = {
    Text = "Tại Quốc gia Bàn Long, mỗi đứa trẻ đều mong chờ sự đến của Lễ cầu năm. \nBánh đậu đỏ, kẹo đậu phộng, kẹo hạnh nhân, cùng với tiền lì xì do cha mẹ và ông bà chuẩn bị, nhận được món quà như vậy chắc chắn sẽ có một năm thuận lợi và may mắn."
  },
  Item_128660_Name = {
    Text = "Hòm cầu phúc năm mới"
  },
  Item_129143_Desc = {
    Text = "Các hạt cảm xúc Dispersi trên chuyến tàu Hạnh phúc, khi chạm vào dường như nghe thấy tiếng cười của \"N\" nhỏ.\nDùng để tăng cường cộng hưởng của người giữ bí mật trong \"Chuyến Tàu Hạnh Phúc Phi Tốc\"."
  },
  Item_129143_Name = {
    Text = "Của trái tim lưu lại hình ảnh"
  },
  Item_129498_Desc = {
    Text = "Khi điểm khách VIP đạt đến một giá trị nhất định, cấp độ \"Thông số phòng sang trọng\" sẽ được nâng cao. Có thể nhận được trong \"Tàu hỏa hạnh phúc lao nhanh\"."
  },
  Item_129498_Name = {
    Text = "Điểm khách VIP"
  },
  Item_129499_Desc = {
    Text = "Ghi lại lệnh khóa này, bạn có thể chọn kỹ năng lệnh khóa:\"Pháo hoa cuối năm\".\n\nNăm năm tháng tháng hoa vẫn giống nhau, năm năm tháng tháng mong đoàn viên.\nTối nay cầu nguyện, một giấc mơ. Mong rằng hoa nhài nhỏ của thiếp bên người bạn cũ, cùng nhau thưởng thức muôn vàn pháo hoa, đừng quên tình nghĩa của thiếp."
  },
  Item_129499_Name = {
    Text = "Hoa lửa cuối năm"
  },
  Item_129499_StoryDesc = {
    Text = "Năm năm tháng tháng hoa vẫn giống nhau, năm năm tháng tháng mong đoàn viên.\n Tối nay cầu nguyện, một giấc mơ. Mong tiểu hoa nhài của thiếp bên người bạn cũ, cùng nhau thưởng thức muôn vàn pháo hoa, đừng quên tình nghĩa của thiếp."
  },
  Item_129628_Desc = {
    Text = "Vòng mệnh với thuộc tính cấp độ sạc chìa khóa bạc."
  },
  Item_129628_Name = {
    Text = "Bước qua hoa hồng trong bùn lầy"
  },
  Item_129628_StoryDesc = {
    Text = "Trong một vòng lặp không thể được ghi lại, Vòng tròn · Ramona bước qua khu vườn hoa sau tháp đồng hồ. \n Cô thoáng nhìn thấy trong khu vườn hoa hồng, những bông hoa đang nở rộ rực rỡ. \n Sau một khoảnh khắc hiếm hoi dừng lại, cô đã bỏ lại tất cả những suy nghĩ vô nghĩa và tiếp tục tiến về chiến trường cuối cùng. \n Bùn đất bắn lên những cánh hoa màu đỏ như máu, ngay lập tức bị dung dịch ăn mòn màu đen nuốt chửng, chỉ để lại một bóng dáng kiêu hãnh trong gió."
  },
  Item_129898_Desc = {
    Text = "Có thể nhận được sau khi mua \"Khóa Đề Cốt Lõi\" trong \"Khóa Đề Học Kỳ\".\n \"Món ăn tao nhã cần thời gian để chạm trổ, a～ tôi mong chờ lắm, hương vị khắc cốt ghi tâm của ngươi.\""
  },
  Item_129898_Name = {
    Text = "Ngày hôm qua không bao giờ phai nhạt: Doresain"
  },
  Item_129898_StoryDesc = {
    Text = "Khóa đề học kỳ kỳ 29"
  },
  Item_130028_Desc = {
    Text = "Vảy phấn thuần khiết vô tì vết, khiến người ta cảm thấy gần gũi, dường như có thể tạo ra sự cộng hưởng kỳ diệu với vườn ươm của Saya.\nMang nó đến cho Saya, có thể nhận được phần thưởng từ cô ấy.\n\nRơi ra ít nhất {s1} cái"
  },
  Item_130028_Name = {
    Text = "Lân phấn thuần bạch"
