  Item_130547_Desc = {
    Text = "Có thể nhận được sau khi mua \"Chủ đề chính\" trong \"Đề tài học kỳ\".\n\"Cái đó... tôi, \"chúng tôi\" có thể đóng rất nhiều Nhân Vật — nếu bạn cần.\""
  },
  Item_130547_Name = {
