  Item_130700_Desc = {
    Text = "Viên than nhỏ, ghét, Mosk, thích! Viên than nhỏ, nộp lên, phần thưởng~\n\nRơi ra ít nhất {s1} cái"
  },
  Item_130700_Name = {
    Text = "Ốc biển số ba"
  },
  Item_130701_Desc = {
    Text = "Viên than nhỏ, thích! Mosk, thích! Thu thập, càng nhiều càng tốt~\n\nRơi ra ít nhất {s1} cái"
  },
  Item_130701_Name = {
    Text = "Ốc biển số một"
  },
  Item_130702_Desc = {
    Text = "Bạn bè, thích, Mosk, thu thập! Giúp đỡ, phần thưởng! Tặng cho bạn bè~\n\nRơi ra ít nhất {s1} cái"
  },
  Item_130702_Name = {
    Text = "Ốc biển số hai"
  },
  Item_130703_Desc = {
    Text = "Ghi lại lệnh khóa này, có thể chọn kỹ năng lệnh khóa:\"Trong trắng của sự chìm đắm\".\n\nDù biết rõ số phận mình sẽ chìm đắm, cô ấy vẫn kiên quyết lao vào biển cả lạnh lẽo.\nBởi vì đây là cách duy nhất trong suy nghĩ ngây thơ của cô để cứu bạn bè."
  },
  Item_130703_Name = {
    Text = "Sự trong sáng của cái chết đuối"
  },
  Item_130703_StoryDesc = {
    Text = "Dù biết chắc chắn sẽ chìm xuống, cô ấy vẫn dũng cảm lao mình vào đại dương lạnh giá. \n Vì đây là cách duy nhất trong suy nghĩ ngây thơ của cô để cứu bạn bè."
  },
  Item_130704_Desc = {
    Text = "Tập trung vào vòng mệnh tăng cường cơn điên cuồng bùng nổ của người sử dụng, có khả năng hồi phục điên cuồng định kỳ trong quá trình khám phá và tăng cường sát thương cơn điên cuồng bùng nổ của họ, khi chuyển sang tư thế Sóng Gẩm sẽ cung cấp một lượng lớn sự thông thạo giới vực."
  },
  Item_130704_Name = {
    Text = "Vườn địa đàng xa xôi"
  },
  Item_130704_StoryDesc = {
    Text = "Đây là một hòn đảo không được ghi chép trên bất kỳ hải đồ nào.\nTừ khi nó ra đời, loại virus mang tên \"Văn Minh\" chưa từng đặt chân lên mảnh đất thuần khiết này.\nNơi đây chỉ có bãi cát, rừng rậm, biển cả mênh mông nhìn không thấy bờ, và... một cô bé nhỏ nhắn.\n.........\n \"Bố, mẹ, cá!\"\n \"Ao~~\"\nHai con cá heo thong thả bơi đến bên chân cô bé, phát ra tiếng kêu trong trẻo du dương.\nMột con cõng cô bé lên, con còn lại đỡ lấy con cá vừa bị đánh ngất trong tay cô bé, nuốt chửng nó.\n \"Ao~~\"\n \"Hehe, Moss! Giỏi lắm!\"\nNhư một đứa trẻ ngây thơ không biết gì về thế sự, cô bé làm một động tác đầy sức mạnh để đáp lại lời khen của \"bố\"\"mẹ\".\n \"Hôm nay, mặt trời! Tốt!\"\n \"Moss! Bố! Mẹ! Đi dạo!\"\nNghe lời cô bé, con cá heo cõng cô bé khẽ rên một tiếng, bắt đầu từ từ bơi vòng quanh hòn đảo nhỏ.\nÁnh nắng ấm áp tỏa xuống người cô bé, xua tan cái ẩm lạnh dai dẳng từ mấy ngày trước, làn gió nhẹ nhàng lướt qua mái tóc cô bé, mang theo hơi thở lười biếng của đại dương.\nTiếng cười, tiếng vỗ nước, tiếng đùa giỡn, trên hòn đảo biệt lập với thế giới không có phiền não do \"Văn Minh\" mang đến, chỉ còn lại tiếng cười nguyên thủy nhất, thuần khiết nhất.\nHai thú một người như mọi khi, trải qua một ngày nguyên sơ và vô ưu.\n.........\nCho đến khi tiếng gọi vô biên ấy nuốt chửng hoàn toàn sự tĩnh lặng này.\n \"Hãy trở về... hãy trở về...\"\n \"@1cần bạn...@2...@4... cần bạn...\""
  },
  Item_130705_Desc = {
    Text = "Bạn bè, thích, Mosk, thu thập! Giúp đỡ, phần thưởng! Tặng cho bạn bè~\n\nRơi ra ít nhất {s1} cái"
