  },
  Item_140512_Name = {
    Text = "Quần Tinh Nở Rộ · Tấn Công"
  },
  Item_140558_Desc = {
    Text = "\"Đây là sự trinh khiết, tình yêu và lòng trung thành mà cô ấy tự nguyện dâng hiến.\""
  },
  Item_140558_Name = {
    Text = "Như Nguyện Sở Cầu"
  },
  Item_140559_Desc = {
    Text = "\"Bí quyết sinh tồn của điều tra viên huyền thoại: cô ấy không bao giờ đánh trận không chuẩn bị.\""
  },
  Item_140559_Name = {
    Text = "Truyền Thuyết Sống"
  },
  Item_140560_Desc = {
    Text = "\"Ký hiệu người gửi tin nhắn chỉ đại diện cho việc nó được gửi từ chiếc điện thoại nào.\""
  },
  Item_140560_Name = {
    Text = "Người Gửi Không Rõ"
  },
  Item_140561_Desc = {
    Text = "\"Cả đời anh chưa từng hoài niệm ánh trăng dưới đáy giếng.\""
  },
  Item_140561_Name = {
    Text = "Trăng Đẹp Quá"
  },
  Item_140562_Desc = {
    Text = "\"Một bên lắng nghe giọng nói của nàng trong giấc mơ, truy tìm bóng hình của nàng, một bên tiếp tục chờ đợi.\""
  },
  Item_140562_Name = {
    Text = "Thế Giới Thuần Bạch"
  },
  Item_140563_Desc = {
    Text = "\"Tôi trong mắt bạn, là sự thật của phía nào đây?\""
  },
  Item_140563_Name = {
    Text = "Chân Lý Mặt Cắt"
  },
  Item_140570_Desc = {
    Text = "Có thể nhận được sau khi mua \"Khóa Học Cốt Lõi\" trong \"Đề Tài Học Kỳ\".\n\"Vùng đất dẫn lối Lemuria… ở ngay cuối tia sáng này.\""
  },
  Item_140570_Name = {
    Text = "Ngày Hôm Qua Không Phai: Pharos"
  },
  Item_140570_StoryDesc = {
    Text = "Đề tài học kỳ số 34"
  },
