  Item_141734_Name = {Text = "Táo Đỏ"},
  Item_141735_Desc = {
    Text = "Quả táo đỏ mọng, tươi rói, tỏa ra hương thơm nồng nàn. Hãy Cúng Tế nó cho nàng tiên để nhận được một số phần thưởng.\n\nRơi ra ít nhất {s1} cái"
  },
  Item_141735_Name = {Text = "Táo Đỏ"},
  Item_141736_Desc = {
    Text = "Tại sao táo kẹo lại quý giá hơn táo vàng? Liệu dưới lớp dối trá có ẩn chứa chút chân thành nào không? Khi bạn bắt đầu suy nghĩ về điều này, bạn đã rơi vào bẫy của lời dối trá thực sự rồi đấy. Thôi hãy mau mang nó đến cho nàng tiên để đổi lấy những phần thưởng thiết thực thôi!\n\nRơi ra ít nhất {s1} cái"
  },
  Item_141736_Name = {
    Text = "Táo Đường"
  },
  Item_141737_Desc = {
    Text = "Rốt cuộc đây là táo mạ vàng hay táo vàng thật sự...? Chỉ có nàng tiên mới biết câu trả lời. Hãy Cúng Tế nó cho nàng tiên để nhận được một số phần thưởng.\n\nRơi ra ít nhất {s1} cái"
  },
  Item_141737_Name = {Text = "Táo Vàng"},
