  Item_52037_Desc = {
    Text = "Đạo cụ dùng để đổi chỗ tại \"bàn thờ linh tủy\". \nHãy dâng hiến tủy của bạn, hỡi người tế tự. Mọi kỳ nguyện, thần quốc sẽ ứng đáp."
  },
  Item_52037_Name = {
    Text = "tủy của người tế lễ"
  },
  Item_52038_Desc = {
    Text = "Đạo cụ được sử dụng để đổi chỗ tại \"bàn tế huyết tinh\". \nNgười hiến tế, hãy dâng máu của mình. Mọi tội lỗi đều bị thần quốc trừng phạt."
  },
  Item_52038_Name = {
    Text = "Máu của người thờ cúng"
  },
  Item_52039_Desc = {
    Text = "Đạo cụ được sử dụng để đổi chỗ tại \"đàn tế ngọc lệ\". \nXin hãy dâng lên nước mắt của bạn, hỡi người tế lễ. Mọi nỗi khổ đau, thần quốc sẽ đền đáp."
  },
  Item_52039_Name = {
