  Item_54470_Desc = {
    Text = "Hoàn thành thành tựu trong sự kiện \"Cánh cửa Vạn Tượng\". \n \"Pụt pụt pụt... Là bạn đã ném chìa khóa bạc vào hồ đen phải không?\""
  },
  Item_54470_Name = {
    Text = "Nhân danh chìa khóa bạc:Tà Vy"
  },
  Item_54470_StoryDesc = {
    Text = "Sự kiện Tà Vy"
  },
  Item_54471_Desc = {
    Text = "\"Hừ, cẩn thận với ví của cậu. Tôi đã trộm được một lần, thì cũng có thể làm lại lần thứ hai. Chưa ai có thể ngăn được tôi, kẻ được mệnh danh là thần trộm số một khu đông Lentiennam!\""
  },
  Item_54471_Name = {
    Text = "Nhân danh chìa khóa bạc:Jenkin"
  },
  Item_54471_StoryDesc = {
    Text = "Hoạt động đặt trước trên Steam"
  },
  Item_54472_Desc = {
    Text = "\"À à... Hôm nay mặt biển cũng thật chói lọi... Hả, ngươi bảo đó là phản chiếu của ánh sáng ta phát ra sao?\""
  },
  Item_54472_Name = {
