  },
  Item_54475_Desc = {
    Text = "Có thể nhận được sau khi mua \"đề tài cốt lõi\" trong \"bản ghi đề tài\". \n \"À... tôi không phải đang mơ màng... đây chỉ là ánh mắt bình thường của tôi...\""
  },
  Item_54475_Name = {
