  Item_59766_Name = {
    Text = "Gói quà liên hoàn 1 Chương 9"
  },
  Item_59776_Desc = {
    Text = "Sau khi mở khóa, hoàn thành tất cả nhiệm vụ trong \"Đào tạo đặc biệt đón thảm họa\" sẽ nhận được thêm những phần thưởng này"
  },
  Item_59776_Name = {
    Text = "Huấn luyện đặc biệt ứng phó thảm họa"
  },
  Item_59777_Name = {
    Text = "Gói Liên Kéo Chương 1-3"
  },
  Item_59781_Name = {
