  Item_70292_Desc = {
    Text = "Có thể nhận được trong \"Vượt Giới Hạn Tinh Tú·Đặt Trước Có Hạn\".\n \"Khi các vì sao xếp đúng vị trí, @1 vĩ đại sẽ xuất hiện trên thế gian.\""
  },
  Item_70292_Name = {
    Text = "Khoảnh khắc chính vị của tinh thần"
  },
  Item_70292_StoryDesc = {
    Text = "Hoạt động đặt trước phiên bản V2.0"
  },
  Item_70919_Desc = {
    Text = "Ghi nhớ lệnh khóa này, có thể chọn kỹ năng lệnh khóa:\"Bảo hộ của Dải Ngân hà\".\n\nÔng ấy đã chọn vương miện đó, và vương miện đó cũng đã chọn ông ấy.\nVua mới và linh hồn của vị thần cổ đại cảm ứng trong khoảnh khắc, bóng ma che trời kín mặt xuất hiện sau lưng ông, mang lại hòa bình vĩnh cửu cho đất nước."
  },
  Item_70919_Name = {
    Text = "Bảo hộ của các ngôi sao"
  },
  Item_70919_StoryDesc = {
    Text = "Anh ta đã chọn vương miện đó, và vương miện đó cũng đã chọn anh ta. \nVua mới và linh hồn của cổ thần đã cảm ứng trong một khoảnh khắc, bóng mờ che phủ bầu trời hiện ra phía sau anh, mang lại sự bình an vĩnh cửu cho đất nước."
  },
  Item_71281_Desc = {
    Text = "Linh hồn bị khổ đau ơi, đừng bao giờ mất hy vọng, Giáo hội nhân từ sẽ cầu nguyện cho ngươi với Cha Trời. \nCó sẵn trong thời gian giới hạn tại \"Chăn dắt linh hồn·Phục chế\"."
  },
  Item_71281_Name = {
    Text = "Lời cầu nguyện trong Thánh lễ"
  },
  Item_71282_Desc = {
    Text = "Linh hồn bị đau khổ, ngươi sẽ được ban thưởng, vị giám mục nhân từ sẽ thay mặt Cha Trời ban cho ngươi phúc lành. \nCó sẵn trong thời gian giới hạn của sự kiện \"Chăn dắt linh hồn·Phục chế\"."
  },
  Item_71282_Name = {
    Text = "Phúc lành sau Thánh lễ"
  },
  Item_71283_Desc = {
    Text = "Linh hồn đau khổ ơi, đừng bối rối, Đức Giám mục nhân từ sẽ chỉ lối cho bạn. \nTrong thời gian sự kiện \"Mục tử của linh hồn · Phục chế\" có sẵn giới hạn."
  },
  Item_71283_Name = {
    Text = "Hướng dẫn trước khi lễ"
  },
  Item_71393_Desc = {
    Text = "Bánh răng tinh vi đại diện cho công nghệ tiên tiến nhất thời đại, có thể thay thế những bộ phận cũ kỹ của búp bê.\nBánh răng linh kiện mà đóa dùng để sửa chữa thân thể. Dùng để đổi vật phẩm cần thiết tại cửa hàng.\n\nRơi ít nhất {s1} cái"
