  Item_73463_Desc = {
    Text = "Cá nướng của Gia Lân?... Hmm?! Mùi vị này... Tại sao lại giống như do Van làm vậy.."
  },
  Item_73463_EmojiName = {
    Text = "Nhìn chằm chằm"
