  Item_78731_Desc = {
    Text = "Có thể nhận được trong \"Đặt mua trước giới hạn · Sóng âm côn trùng\". \n\n \"Trong sự cộng hưởng của tiếng vo ve không thể gọi tên, thực tại dần bị cuốn đi. Một mạng lưới âm thanh dệt nên bởi huyết nhục đã bủa vây tất cả.\""
  },
  Item_78731_Name = {
