  Item_9507_Desc = {
    Text = "Thuộc tính chính được chọn ngẫu nhiên từ cấp độ hồi nạp điên cuồng, kháng cự tử vong, cấp độ sạc chìa khóa bạc và sát thương hiệu quả."
  },
  Item_9507_Name = {
    Text = "Thi phẩm hình vòng Ⅴ"
  },
  Item_9507_StoryDesc = {
    Text = "Trôi nổi trong khe hở của dòng thời gian tuần hoàn."
  },
  Item_9508_Desc = {
    Text = "Để duy trì sự tồn tại của loài người. \n Những ký ức được bảo tồn trong khung hình, dùng làm nguyên liệu để thăng cấp giới vực thịt máu và đánh thức thân thể được đánh thức."
  },
  Item_9508_Name = {
    Text = "Bản sao ký ức"
