  Item_9520_Name = {
    Text = "Tháng Tư Tiễn Táng Ⅲ"
  },
  Item_9520_StoryDesc = {
    Text = "Anh ta được chôn cất vào mùa xuân năm @2."
  },
  Item_9521_Desc = {
    Text = "Bò lết, vặn vẹo, chúng ta bò lê trong bóng tối……rít……rít……\nkén sâu bị ký sinh. Được sử dụng để nâng cấp kỹ năng của thân thể được đánh thức trong giới vực thịt máu."
  },
  Item_9521_Name = {
    Text = "Pupa Côn Trùng Bản Địa"
  },
  Item_9522_Desc = {
    Text = "Dùng để khóa tối đa hai thuộc tính phụ khi Hoàn Ký, ngoài ra cũng thể dùng để đổi lại thành tàn dư của những Khế Ước. \nCho đến tận bây giờ, ngòi bút vẫn còn vương vấn những nét mực uốn lượn ngày xưa."
  },
  Item_9522_Name = {
    Text = "Bút Lông Hoài Cổ"
  },
  Item_9523_Desc = {
