  },
  Item_9599_Name = {
    Text = "Nghi Lễ Quang Hợp II"
  },
  Item_9599_StoryDesc = {
    Text = "Khoa học phân tích quang phổ, nghệ thuật phân tích quang hợp."
  },
  Item_9600_Desc = {
    Text = "Trang phục: \nThần giáng cơ khí I\nThần giáng cơ khí II\nThần giáng cơ khí III\nThần giáng cơ khí IV\nThần giáng cơ khí V\nThần giáng cơ khí VI"
  },
  Item_9600_Name = {
    Text = "Sự xuống máy"
  },
  Item_9601_Desc = {
    Text = "Bò lết, lăn lê, vặn vẹo, chúng ta trở mình trong bóng tối… rít… rít…\nMột chiếc kén đã bị kí sinh. Được sử dụng để nâng cấp kỹ năng của Thể Thức Tỉnh cõi Huyết Nhục."
  },
  Item_9601_Name = {
    Text = "Kén Nhộng Tươi"
  },
  Item_9602_Name = {Text = "báo chí"},
  Item_9603_Desc = {
    Text = "Thế giới đã quên tên của cô ấy, vì vậy hình bóng trắng tinh khôi như hoa bách hợp được vội vàng gọi là \"Lily\". \n·Đánh đổi bằng sức sống, tạo ra lá chắn cao \n·Càng bị thương nặng, sát thương gây ra càng cao"
  },
  Item_9603_Name = {Text = "Lily"},
  Item_9604_Desc = {
    Text = "Ban cho chúng tôi một tinh thần bí ẩn. \n Xuất phát từ phim đặc biệt của Hội thơ Philin, có khả năng chuyển ghi tinh thần con người. \n Dùng làm vật liệu để thăng cấp thân thể được đánh thức trong siêu không gian giới vực."
  },
