  Item_9760_Desc = {
    Text = "Các thuộc tính chính sẽ ngẫu nhiên giữa Khuếch Đại Sát Thương, Kháng Tử, Thông Thạo Giới Vực, Hiệu Quả Hắc Kim."
  },
  Item_9760_Name = {
    Text = "Nghi Lễ Quang Hợp Ⅵ"
  },
  Item_9760_StoryDesc = {
    Text = "Khoa học phân tích quang phổ, nghệ thuật phân tích quang hợp."
  },
  Item_97610_Desc = {
    Text = "Cô ấy không thể thoát khỏi giấc mơ đó, cô ấy đã quyết định không thức dậy nữa, hãy để cô ấy tiếp tục ngủ yên, cô ấy sẽ ban cho bạn phần thưởng xứng đáng.\n\nRơi ra ít nhất {s1} cái"
  },
  Item_97610_Name = {
    Text = "Hương Liệu Bắt Mộng"
  },
  Item_97611_Desc = {
    Text = "Một bó thảo mộc khi đốt lên có tác dụng an thần, giúp cô bé vẫn hay bị ác mộng đánh thức trong những đêm ở Misaque có được giấc ngủ ngon.\n\nRơi ra ít nhất {s1} cái"
  },
  Item_97611_Name = {
