  Item_9990_Name = {
    Text = "Thi phẩm hình vòng Ⅳ"
  },
  Item_9990_StoryDesc = {
    Text = "Trôi nổi trong khe hở của dòng thời gian tuần hoàn."
  },
  Item_9991_Desc = {
    Text = "Ghi lại lệnh khóa này, bạn có thể chọn kỹ năng lệnh khóa:\"đổi chỗ không công bằng\". \n\nMisaque luôn không khuyến khích tôi tiếp xúc quá nhiều với người thương nhân kia, nhưng nếu để cứu tất cả mọi người khỏi vùng đầm lầy này..."
