  Item_9994_Name = {
    Text = "Nghịch Lý Ⅴ"
  },
  Item_9994_StoryDesc = {
    Text = "Tình cờ không thể tránh khỏi. Hữu hạn nhưng vô vàn khả năng."
  },
  Item_9995_Desc = {
    Text = "Ghi lại lệnh khóa này, bạn có thể chọn kỹ năng lệnh khóa:\"lễ tang bất diệt\" khi ở trong biên đội. \n\nTôi chẳng giúp được gì nhiều cho cô ấy, cô ấy đã ngăn chặn sự giáng thế của vị thần giả mạo bằng chính sức mạnh của mình. \nLinh hồn của cô ấy sẽ không biến mất, cô ấy sẽ mãi tỏa sáng như một ngôi sao tự do."
  },
  Item_9995_Name = {
    Text = "lễ tang bất diệt"
  },
  Item_9995_StoryDesc = {
    Text = "Tôi không thể giúp cô ấy nhiều, cô ấy đã ngăn chặn sự giáng thế của vị thần giả mạo bằng chính sức mạnh của mình. \nLinh hồn của cô ấy sẽ không tiêu tử, cô ấy sẽ mãi mãi tỏa sáng như một ngôi sao tự do."
  },
  Item_9996_Desc = {
    Text = "Các thuộc tính chính sẽ ngẫu nhiên giữa Khuếch Đại Sát Thương, Kháng Tử, Thông Thạo Giới Vực, Hiệu Quả Hắc Kim."
  },
  Item_9996_Name = {
    Text = "Hồi Hương Hướng Hải Vực Ⅵ"
  },
  Item_9996_StoryDesc = {
    Text = "Hãy trở về đi, hỡi thành phố cổ xưa, nơi chắc chắn sẽ trỗi dậy một lần nữa."
  },
  Item_9997_Desc = {
    Text = "Vòng mệnh có thuộc tính là giới vực thông thạo."
  },
  Item_9997_Name = {Text = "Lưu đày"},
  Item_9997_StoryDesc = {
    Text = "Linh hồn tôi là một ngôi mộ."
  },
  Item_9998_Desc = {
    Text = "Tăng khả năng hồi phục sức sống của người sở hữu, có thể biến đổi sức sống thành khiên và sức mạnh tạm thời sau khi chịu sát thương."
  },
  Item_9998_Name = {
    Text = "Ngụ ngôn của kẻ tham ăn"
  },
  Item_9998_StoryDesc = {
    Text = "<Bold:24 tháng 1>\nTrên người có mùi hôi hám.\nHôm nay khi trở về nhà cùng đầy tớ Teresa, chúng tôi đi qua khu Nam An Phú.\nĐây không phải là một trải nghiệm dễ chịu.\nĐó là một nơi nguy hiểm@2 có một số gã trên người mọc những vết thương kỳ lạ, giống như những lỗ hình tam giác.\nĐầy tớ Teresa nói đây là hình phạt của Chúa dành cho những kẻ ngoại giáo.\n\n<Bold:22 tháng 2>\nSốt đã một tháng.\nHôm nay cuối cùng cũng ăn được chút gì đó. Là thịt bò tươi, mềm và nhiều nước…\nĐúng, nhiều nước.\nMùi vị ngọt ngào@2 màu đỏ@2\nTất cả gương trong nhà đều bị cất đi, ngay cả Bobby cũng không dám nhìn tôi.\nHe he. Họ không biết, vào ban đêm, tôi có thể thấy hình dạng của mình từ cái bóng trên cửa sổ.\nTrên mặt, cổ, và ngực tôi… từ trên xuống dưới, đầy rẫy,\nmọc đầy những hình tam giác@2 màu đen\n\n<Bold:17 tháng 3>\nMàng mắt tôi như bị phủ một lớp voan đỏ.\nThế giới trở thành màu máu@3\nCha tôi đứng trong sương máu gọi tôi, đây là lần đầu tiên ông nói với tôi bằng giọng lớn như vậy.\nÔng ở rất gần tôi, nhưng giọng nói lại xa vời. Tôi ngửi thấy sự tuyệt vọng, sự ghê tởm và máu.\nĐừng@2 đưa tôi đi, đừng……"
  },
